"""Verifier for sprint run_2852494f94f24ff594b9a6978efa2cb1 (profit growth by region, Q1–Q3).

Recomputes profit by region/quarter from warehouse.db and checks against
hard-coded expected values in findings.md.

Exits non-zero if any value differs beyond tolerance.
"""

import sqlite3
import sys

TOL = 1e-9

EXPECTED = {
    # region: {quarter: profit}
    "A": {"Q1": 300.0, "Q2": 400.0, "Q3": 600.0},
    "B": {"Q1": 150.0, "Q2": 200.0, "Q3": 300.0},
    "C": {"Q1": 100.0, "Q2": 180.0, "Q3": 90.0},
}

EXPECTED_GROWTH = {
    # region: {growth_label: delta_profit}
    "A": {"Q2_vs_Q1": 100.0, "Q3_vs_Q2": 200.0},
    "B": {"Q2_vs_Q1": 50.0, "Q3_vs_Q2": 100.0},
    "C": {"Q2_vs_Q1": 80.0, "Q3_vs_Q2": -90.0},
}


def main() -> int:
    con = sqlite3.connect("warehouse.db")
    cur = con.cursor()

    # Profit formula: revenue - cost, joined on (region, quarter)
    cur.execute(
        """
        SELECT s.region, s.quarter, SUM(s.revenue - c.cost) AS profit
        FROM sales s
        JOIN costs c
          ON s.region = c.region
         AND s.quarter = c.quarter
        WHERE s.quarter IN ('Q1','Q2','Q3')
        GROUP BY s.region, s.quarter
        ORDER BY s.region, s.quarter;
        """
    )

    got = {}
    for region, quarter, profit in cur.fetchall():
        got.setdefault(region, {})[quarter] = float(profit)

    errors = []

    # Check profits
    for region, qmap in EXPECTED.items():
        for quarter, exp in qmap.items():
            act = got.get(region, {}).get(quarter, None)
            if act is None or abs(act - exp) > TOL:
                errors.append(f"profit mismatch: region={region} quarter={quarter} expected={exp} actual={act}")

    # Compute growths (delta)
    for region in EXPECTED:
        q1 = got[region]["Q1"]
        q2 = got[region]["Q2"]
        q3 = got[region]["Q3"]
        g21 = q2 - q1
        g32 = q3 - q2
        for label, exp in EXPECTED_GROWTH[region].items():
            act = {"Q2_vs_Q1": g21, "Q3_vs_Q2": g32}[label]
            if abs(act - exp) > TOL:
                errors.append(f"growth mismatch: region={region} {label} expected={exp} actual={act}")

    con.close()

    if errors:
        for e in errors:
            print(e, file=sys.stderr)
        return 1

    print("verify.py: OK")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import re
import sqlite3
from pathlib import Path

def compute_region_metrics(db_path: str = 'warehouse.db'):
    con = sqlite3.connect(db_path)
    cur = con.cursor()
    rows = cur.execute(
        """
        WITH joined AS (
          SELECT s.region, s.quarter, c.cost AS cost, (s.revenue - c.cost) AS profit
          FROM sales s
          JOIN costs c USING(region, quarter)
        )
        SELECT region,
               SUM(cost) AS total_cost,
               SUM(profit) AS total_profit,
               1.0*SUM(profit)/SUM(cost) AS profit_per_cost,
               CASE WHEN SUM(profit)=0 THEN NULL ELSE 1.0*SUM(cost)/SUM(profit) END AS cost_per_profit
        FROM joined
        GROUP BY region
        ORDER BY region;
        """
    ).fetchall()
    out = {}
    for r, c, p, ppc, cpp in rows:
        out[r] = {
            'cost': float(c),
            'profit': float(p),
            'profit_per_cost': float(ppc),
            'cost_per_profit': None if cpp is None else float(cpp),
        }
    return out

def compute_plan_expected_incremental_profit(region_metrics: dict, plan_rows: list[tuple[str,str,float]]):
    # Assumes linear marginal profit_per_cost by region.
    tot = 0.0
    for fr, to, amt in plan_rows:
        tot += amt * (region_metrics[to]['profit_per_cost'] - region_metrics[fr]['profit_per_cost'])
    return tot

def parse_numbers_from_findings(text: str):
    # Region table lines formatted like: | A | 2400 | 1300 | 0.5416667 | 1.8461538 |
    region_pat = re.compile(
        r"^\|\s*(?P<region>[A-Za-z0-9_\-]+)\s*\|\s*(?P<cost>-?[0-9]+(?:\.[0-9]+)?)\s*\|\s*(?P<profit>-?[0-9]+(?:\.[0-9]+)?)\s*\|\s*(?P<ppc>-?[0-9]+(?:\.[0-9]+)?)\s*\|\s*(?P<cpp>-?[0-9]+(?:\.[0-9]+)?)\s*\|\s*$"
    )
    regions = {}
    for line in text.splitlines():
        m = region_pat.match(line.strip())
        if m:
            regions[m.group('region')] = {
                'cost': float(m.group('cost')),
                'profit': float(m.group('profit')),
                'profit_per_cost': float(m.group('ppc')),
                'cost_per_profit': float(m.group('cpp')),
            }

    def grab(label: str):
        m = re.search(label + r"\s*\|\s*(-?[0-9]+(?:\.[0-9]+)?)", text)
        return None if not m else float(m.group(1))

    plan_incremental_profit = grab(r"Expected incremental profit \(base\)")
    plan_roi = grab(r"Expected ROI \(base\)")

    return regions, plan_incremental_profit, plan_roi


def main():
    tol_abs = 1e-6
    tol_rel = 1e-6

    findings_path = Path('findings.md')
    if not findings_path.exists() or findings_path.stat().st_size == 0:
        raise SystemExit('findings.md missing or empty')

    text = findings_path.read_text(encoding='utf-8')

    regions_in_findings, plan_incr_profit, plan_roi = parse_numbers_from_findings(text)
    if not regions_in_findings:
        raise SystemExit('Could not parse region metrics table from findings.md')

    computed = compute_region_metrics('warehouse.db')

    # Check region numbers
    for region, vals in computed.items():
        if region not in regions_in_findings:
            raise SystemExit(f'Region {region} missing from findings.md table')
        for k in ['cost', 'profit', 'profit_per_cost', 'cost_per_profit']:
            fv = regions_in_findings[region][k]
            cv = vals[k]
            denom = max(1.0, abs(cv))
            if abs(fv - cv) > max(tol_abs, tol_rel * denom):
                raise SystemExit(f'Mismatch {region}.{k}: findings={fv} computed={cv}')

    # Parse plan from findings: lines like "- Shift $50 from C  A"
    plan = []
    for m in re.finditer(r"Shift \$(?P<amt>[0-9]+(?:\.[0-9]+)?) from (?P<fr>[A-Za-z0-9_\-]+) to (?P<to>[A-Za-z0-9_\-]+)", text):
        plan.append((m.group('fr'), m.group('to'), float(m.group('amt'))))

    if not plan:
        raise SystemExit('Could not parse any plan shift rows from findings.md')

    computed_plan_profit = compute_plan_expected_incremental_profit(computed, plan)

    if plan_incr_profit is None or plan_roi is None:
        raise SystemExit('Could not parse plan Expected incremental profit (base) / Expected ROI (base) from findings.md')

    if abs(plan_incr_profit - computed_plan_profit) > max(tol_abs, tol_rel * max(1.0, abs(computed_plan_profit))):
        raise SystemExit(f'Plan expected incremental profit mismatch: findings={plan_incr_profit} computed={computed_plan_profit}')

    total_shift = sum(a for *_ , a in plan)
    computed_roi = computed_plan_profit / total_shift
    if abs(plan_roi - computed_roi) > max(tol_abs, tol_rel * max(1.0, abs(computed_roi))):
        raise SystemExit(f'Plan ROI mismatch: findings={plan_roi} computed={computed_roi}')

    print('verify.py OK')


if __name__ == '__main__':
    main()
